120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        // The effective registration date (supplied, or the server date when omitted) must fall on
124	        // a business day: a weekend rolls forward to the next Monday. Everything derived from the
125	        // registration date — the stored value, the per-day limit below and the membership number —
126	        // uses this adjusted date.
127	        LocalDate effectiveDate = BusinessDays.effectiveRegistrationDate(owner.getRegistrationDate());
128	        owner.setRegistrationDate(effectiveDate);
129	        // Per-day capacity: once the day has reached its limit of newly created owners, reject
130	        // further creates for that day with 429 Too Many Requests.
131	        int ownersRegisteredToday = this.clinicService.countOwnersRegisteredOn(effectiveDate);
132	        if (ownersRegisteredToday >= DAILY_REGISTRATION_LIMIT) {
133	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
134	        }
135	        // Bulk-signup warning: flag this owner when more than 80 owners have already been created
136	        // for its registration date, signalling a bulk-signup surge.
137	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
138	        // Per-city capacity: a city that already holds the maximum number of owners is full.
139	        if (this.clinicService.countOwnersInCity(owner.getCity()) >= CITY_CAPACITY) {
140	            return new ResponseEntity<>(HttpStatus.CONFLICT);
141	        }
142	        // When the owner acknowledges sharing a household with an existing owner (same last name
143	        // and address), assign the shared, stable household identifier (back-filling the existing
144	        // member(s)) before the identity key is computed, so household members carry the same
145	        // householdId component.
146	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
147	        if (sharesHousehold
148	            && this.clinicService.isHouseholdInUse(owner.getLastName(), owner.getAddress())) {
149	            this.clinicService.assignHousehold(owner);
150	        }
151	        // Consolidated duplicate detection: the former separate telephone, email and household
152	        // checks are now expressed through a single derived identityKey. Reject with 409 only when
153	        // the new owner's WHOLE identityKey (normalized telephone | email-or-empty | householdId)
154	        // equals an existing owner's; an exact full-key match is the only duplicate.
155	        if (this.clinicService.isIdentityKeyInUse(owner)) {
156	            return new ResponseEntity<>(HttpStatus.CONFLICT);
157	        }
158	        owner.setNamesakeCount(
159	            this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
160	        this.clinicService.saveOwner(owner);
161	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
162	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
163	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
164	        headers.setLocation(UriComponentsBuilder.newInstance()
165	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
166	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
167	    }
