11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	
15	import java.util.Collection;
16	import java.util.List;
17	import java.util.Map;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
28	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
29	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
30	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
31	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
32	    OwnerDto toOwnerDto(Owner owner);
33	
34	    /**
35	     * Derive an owner's preferred contact channel from its stored contact details:
36	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
37	     */
38	    default String formatContactPreference(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
43	        return hasEmail ? "EMAIL" : "PHONE";
44	    }
45	
46	    /**
47	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
48	     * (e.g. for owners created before the flag existed) to {@code false} so the response
49	     * always carries an explicit boolean.
50	     */
51	    default Boolean formatBulkSignupWarning(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
56	    }
57	
58	    /**
59	     * Known city-to-region mappings. Keyed by the exact city name, the canonical region
60	     * string is returned for a listed city and {@code "UNKNOWN"} for anything else.
61	     */
62	    Map<String, String> CITY_REGIONS = Map.of(
63	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
64	
65	    /**
66	     * Canonical region ranges keyed by region, each an inclusive 4-digit postcode range
67	     * {@code {low, high}}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099.
68	     */
69	    Map<String, int[]> REGION_RANGES = Map.of(
70	        "NSW", new int[] {2000, 2099},
71	        "VIC", new int[] {3000, 3099},
72	        "QLD", new int[] {4000, 4099});
73	
74	    /**
75	     * Derive an owner's locality, preferring the postcode: when the owner has a 4-digit
76	     * postcode that falls in a known region range ({@link #REGION_RANGES}), that region
77	     * is returned. Otherwise (the postcode is absent or in no known range) it falls back
78	     * to the fixed {@link #CITY_REGIONS} city-to-region table, returning the canonical
79	     * region string or {@code "UNKNOWN"} when the city is {@code null} or not listed.
80	     * This returns the same region for known cities but disambiguates cities that share
81	     * a name. Returns {@code null} only when the owner itself is {@code null}.
82	     */
83	    default String formatLocality(Owner owner) {
84	        if (owner == null) {
85	            return null;
86	        }
87	        String postcode = owner.getPostcode();
88	        if (postcode != null && postcode.matches("[0-9]{4}")) {
89	            int value = Integer.parseInt(postcode);
90	            for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
91	                int[] range = entry.getValue();
92	                if (value >= range[0] && value <= range[1]) {
93	                    return entry.getKey();
94	                }
95	            }
96	        }
97	        return CITY_REGIONS.getOrDefault(owner.getCity(), "UNKNOWN");
98	    }
99	
100	    /**
101	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
102	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
103	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
104	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
105	     * nothing. Level {@code 4} is reserved for tenure.
106	     */
107	    default Integer formatMembershipLevel(Owner owner) {
108	        if (owner == null) {
109	            return null;
110	        }
111	        int level = 1;
112	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
113	        if (hasEmail) {
114	            level++;
115	        }
116	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
117	        if (uniqueName) {
118	            level++;
119	        }
120	        return Math.min(level, 3);
121	    }
122	
123	    /**
124	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
125	     * is the last two digits of the registration date year (e.g. {@code "TOW-SMI-0007-M26"}).
126	     * Returns {@code null} when either the customer code or registration date is absent, since
